import React, { useState, useEffect } from "react";
import "../styles/CreateArticlesAdmin.css";

function CreateArticlePage() {
  const [mode, setMode] = useState("article"); // "article" або "poll"

  // дані для статті
  const [articleData, setArticleData] = useState({
    title: "",
    slug: "",
    content: "",
    excerpt: "",
    status: "draft",
    type: "standard",
    category: "sport",
    is_premium: false,
    image: null,
  });

  // дані для опитування
  const [pollQuestion, setPollQuestion] = useState("");
  const [pollOptions, setPollOptions] = useState(["", ""]);
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const token = localStorage.getItem("token");

  // завантаження каналів
  useEffect(() => {
    const fetchChannels = async () => {
      try {
        const res = await fetch("http://127.0.0.1:8000/api/channels/", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.ok) {
          const data = await res.json();
          setChannels(Array.isArray(data) ? data : data.results || []);
        }
      } catch (err) {
        console.error("Не вдалося завантажити канали:", err);
      }
    };
    fetchChannels();
  }, [token]);

  // зміна полів статті
  const handleArticleChange = (e) => {
    const { name, value, type, checked, files } = e.target;
    if (type === "checkbox") {
      setArticleData({ ...articleData, [name]: checked });
    } else if (type === "file") {
      setArticleData({ ...articleData, [name]: files[0] });
    } else {
      setArticleData({ ...articleData, [name]: value });
    }
  };

  // зміна варіантів відповіді
  const handleOptionChange = (index, value) => {
    const newOptions = [...pollOptions];
    newOptions[index] = value;
    setPollOptions(newOptions);
  };

  const addOption = () => setPollOptions([...pollOptions, ""]);
  const removeOption = (index) => {
    const newOptions = pollOptions.filter((_, i) => i !== index);
    setPollOptions(newOptions);
  };

  // сабміт статті
  const handleArticleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();
    Object.entries(articleData).forEach(([key, value]) => data.append(key, value));

    try {
      const res = await fetch("http://127.0.0.1:8000/api/articles/", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: data,
      });

      if (res.ok) {
        alert("✅ Статтю успішно створено!");
        window.location.href = "/";
      } else {
        const err = await res.json();
        console.error("Помилка:", err);
        alert(`Помилка при створенні статті: ${JSON.stringify(err)}`);
      }
    } catch (error) {
      console.error("Помилка запиту:", error);
    }
  };

  // сабміт опитування
  const handlePollSubmit = async (e) => {
    e.preventDefault();

    if (!pollQuestion.trim()) {
      alert("Введіть питання!");
      return;
    }
    const filteredOptions = pollOptions.filter((o) => o.trim() !== "");
    if (filteredOptions.length < 2) {
      alert("Має бути щонайменше два варіанти відповіді!");
      return;
    }

    // 1. створюємо статтю типу "interactive"
    const articleForm = new FormData();
    articleForm.append("title", pollQuestion);
    articleForm.append("slug", pollQuestion.toLowerCase().replace(/\s+/g, "-"));
    articleForm.append("content", ""); // без тексту
    articleForm.append("excerpt", "");
    articleForm.append("status", "published");
    articleForm.append("type", "interactive");
    articleForm.append("category", "News");
    articleForm.append("is_premium", "false");
    if (selectedChannel) articleForm.append("channel", selectedChannel);

    const articleRes = await fetch("http://127.0.0.1:8000/api/articles/", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: articleForm,
    });

    if (!articleRes.ok) {
      const err = await articleRes.json();
      console.error("Помилка створення статті для опитування:", err);
      alert("Не вдалося створити опитування");
      return;
    }

    const article = await articleRes.json();

    // 2. створюємо poll
    const pollRes = await fetch("http://127.0.0.1:8000/api/polls/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        article: article.id,
        question: pollQuestion,
        choices: filteredOptions.map((text) => ({ text })),
      }),
    });

    if (pollRes.ok) {
      alert("✅ Опитування створено!");
      window.location.href = "/";
    } else {
      const err = await pollRes.json();
      console.error("Помилка створення опитування:", err);
      alert("Не вдалося створити опитування");
    }
  };

  return (
    <div className="create-article-container">
      <h2>Створення контенту</h2>

      {/* Вибір режиму */}
      <div className="mode-switch">
        <button
          type="button"
          onClick={() => setMode("article")}
          className={mode === "article" ? "active" : ""}
        >
          📰 Стаття
        </button>
        <button
          type="button"
          onClick={() => setMode("poll")}
          className={mode === "poll" ? "active" : ""}
        >
          📊 Опитування
        </button>
      </div>

      {/* Форма для статті */}
      {mode === "article" && (
        <form onSubmit={handleArticleSubmit} className="create-article-form">
          <input
            type="text"
            name="title"
            placeholder="Заголовок"
            value={articleData.title}
            onChange={handleArticleChange}
            required
          />
          <input
            type="text"
            name="slug"
            placeholder="Slug"
            value={articleData.slug}
            onChange={handleArticleChange}
            required
          />
          <textarea
            name="content"
            placeholder="Основний текст"
            rows="6"
            value={articleData.content}
            onChange={handleArticleChange}
            required
          />
          <textarea
            name="excerpt"
            placeholder="Короткий опис"
            rows="3"
            value={articleData.excerpt}
            onChange={handleArticleChange}
          />

          <label>Категорія:</label>
          <select
            name="category"
            value={articleData.category}
            onChange={handleArticleChange}
          >
            <option value="sport">Спорт</option>
            <option value="fashion">Мода</option>
            <option value="News">Новини</option>
          </select>

          <label>Картинка:</label>
          <input
            type="file"
            name="image"
            accept="image/*"
            onChange={handleArticleChange}
          />

          <button type="submit" className="create-article-button">
            Створити статтю
          </button>
        </form>
      )}

      {/* Форма для опитування */}
      {mode === "poll" && (
        <form onSubmit={handlePollSubmit} className="create-article-form">
          <h3>Опитування</h3>

          <label>Питання:</label>
          <input
            type="text"
            value={pollQuestion}
            onChange={(e) => setPollQuestion(e.target.value)}
            placeholder="Введіть питання"
            required
          />

          <label>Канал:</label>
          <select
            value={selectedChannel}
            onChange={(e) => setSelectedChannel(e.target.value)}
          >
            <option value="">-- Виберіть канал --</option>
            {channels.map((ch) => (
              <option key={ch.id} value={ch.id}>
                {ch.name}
              </option>
            ))}
          </select>

          <label>Варіанти відповідей:</label>
          {pollOptions.map((opt, idx) => (
            <div key={idx} className="poll-option">
              <input
                type="text"
                value={opt}
                onChange={(e) => handleOptionChange(idx, e.target.value)}
                placeholder={`Варіант ${idx + 1}`}
                required
              />
              {pollOptions.length > 2 && (
                <button
                  type="button"
                  onClick={() => removeOption(idx)}
                  className="remove-option"
                >
                  ✖
                </button>
              )}
            </div>
          ))}
          <button type="button" onClick={addOption}>
            ➕ Додати варіант
          </button>

          <button type="submit" className="create-article-button">
            Створити опитування
          </button>
        </form>
      )}
    </div>
  );
}

export default CreateArticlePage;
